  private void seed(String destinationName, List<P> places){
    Destination d = destinations.findByNameIgnoreCase(destinationName).orElse(null);
    if(d == null) return;
    Set<String> existingNames = new HashSet<>();
    for (Attraction existing : attractions.findByDestinationId(d.getId())) {
      existingNames.add(existing.getName().toLowerCase(Locale.ROOT));
    }
    for(P x: places){
      if (!existingNames.add(x.name().toLowerCase(Locale.ROOT))) continue;
      Attraction a = new Attraction();
      a.setDestinationId(d.getId()); a.setName(x.name()); a.setCategory(x.category()); a.setDistanceKm(x.km());
      a.setEstimatedMinutes(x.min()); a.setBestFor(x.bestFor()); a.setVisitDuration(x.duration()); a.setDescription(x.description());
      a.setImageUrl(x.image()); a.setMapUrl("https://www.google.com/maps/search/?api=1&query=" + enc(x.name()+", "+d.getName()+", India"));
      attractions.save(a);
    }
  }
  private static P p(String n,String c,double km,int min,String best,String dur,String desc,String img){return new P(n,c,km,min,best,dur,desc,img);}
  private static String enc(String s){ return s.trim().replace(" ", "+").replace(",", "%2C"); }
